-- Separate Cars V1 identities preserve all existing two-wheeler tables/contracts.
begin;
set local lock_timeout='5s'; set local statement_timeout='60s';
create table public.car_source_snapshots (
  id uuid primary key default gen_random_uuid(), source_file text not null,
  sha256 text not null check (sha256 ~ '^[0-9a-f]{64}$'), row_count integer not null check(row_count=578),
  unique(source_file,sha256)
);
create table public.car_contract_versions (
  id uuid primary key default gen_random_uuid(), contract_key text not null unique,
  definition jsonb not null check(jsonb_typeof(definition)='object'),
  snapshot_id uuid not null references public.car_source_snapshots(id), new_assignment_enabled boolean not null default false
);
create table public.car_category_contracts (
  category_id uuid not null references public.categories(id), version_id uuid not null references public.car_contract_versions(id),
  source_path jsonb not null, fields jsonb not null, source_provenance jsonb not null, display_order integer not null,
  primary key(category_id,version_id), check(jsonb_typeof(fields)='array'), check(jsonb_array_length(source_path)=3)
);
create table public.car_brands (
  id uuid primary key default gen_random_uuid(), label text not null unique check(length(btrim(label))>0)
);
create table public.car_models (
  id uuid primary key default gen_random_uuid(), brand_id uuid not null references public.car_brands(id),
  label text not null check(length(btrim(label))>0), unique(brand_id,label), unique(id,brand_id)
);
create table public.car_catalogue_rows (
  snapshot_id uuid not null references public.car_source_snapshots(id), model_id uuid not null references public.car_models(id),
  source_row integer not null check(source_row>=2), source_order integer not null check(source_order>=0),
  raw jsonb not null check(jsonb_typeof(raw)='object'), selection_enabled boolean not null default true,
  primary key(snapshot_id,model_id), unique(snapshot_id,source_row), check(source_row=source_order+2)
);
create table public.listing_car_contexts (
  listing_id uuid primary key references public.listings(id) on delete cascade,
  category_id uuid not null, version_id uuid not null,
  mode text not null check(mode in ('unanswered','catalogue','unresolved','not_listed')),
  brand_id uuid references public.car_brands(id), model_id uuid,
  brand_text text, model_text text, classification_review_required boolean not null default false,
  foreign key(category_id,version_id) references public.car_category_contracts(category_id,version_id),
  foreign key(model_id,brand_id) references public.car_models(id,brand_id),
  check((mode='unanswered' and model_id is null and brand_text is null and model_text is null)
    or (mode in ('catalogue','unresolved') and brand_id is not null and model_id is not null and brand_text is null and model_text is null)
    or (mode='not_listed' and brand_id is null and model_id is null and brand_text is not null and model_text is not null and length(btrim(brand_text)) between 1 and 100 and length(btrim(model_text)) between 1 and 150))
);

-- No inherited default grants: reference reads only, contexts owner-only with existing account/policy guards.
do $$ declare t text; begin
  foreach t in array array['car_source_snapshots','car_contract_versions','car_category_contracts','car_brands','car_models','car_catalogue_rows'] loop
    execute format('alter table public.%I enable row level security',t);
    execute format('revoke all on public.%I from public, anon, authenticated, service_role',t);
    execute format('grant select on public.%I to authenticated',t);
    execute format('create policy reference_read on public.%I for select to authenticated using (true)',t);
  end loop;
end $$;
alter table public.listing_car_contexts enable row level security;
revoke all on public.listing_car_contexts from public,anon,authenticated,service_role;
grant select,insert,update on public.listing_car_contexts to authenticated;
create policy car_context_read on public.listing_car_contexts for select to authenticated using (
  exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()))
);
create policy car_context_insert on public.listing_car_contexts for insert to authenticated with check (
  exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()) and l.status='draft')
  and app_security.get_account_status((select auth.uid()))='active' and app_security.has_current_policy_acceptance((select auth.uid()))
);
create policy car_context_update on public.listing_car_contexts for update to authenticated using (
  exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()) and l.status='draft')
  and app_security.get_account_status((select auth.uid()))='active' and app_security.has_current_policy_acceptance((select auth.uid()))
) with check (
  exists(select 1 from public.listings l where l.id=listing_id and l.seller_id=(select auth.uid()) and l.status='draft')
  and app_security.get_account_status((select auth.uid()))='active' and app_security.has_current_policy_acceptance((select auth.uid()))
);

-- New-only car validation delegates unchanged answer semantics to the existing validator.
create function app_security.validate_car_answers(a jsonb,fields jsonb,previous jsonb default '{}'::jsonb)
returns jsonb language plpgsql set search_path='' as $$
declare k text; v jsonb; status text; value text; n numeric; normalized jsonb; extras text[]:=array['fuel_type','transmission','powertrain','seating_capacity','battery_capacity_kwh','range_km']; electric boolean:=fields ? 'battery_capacity_kwh';
begin
  if jsonb_typeof(a) is distinct from 'object' then raise exception using errcode='22023',message='Car answers must be an object'; end if;
  if a ? 'condition' then raise exception using errcode='22023',message='Condition uses the common item field'; end if;
  normalized:=app_security.validate_vehicle_answers(a-extras,fields,previous-extras);
  for k,v in select * from jsonb_each(a) where key=any(extras) loop
    if not fields ? k and not (electric and k='powertrain') then raise exception using errcode='22023',message='Car field does not apply to this category'; end if;
    if k='seating_capacity' then
      if jsonb_typeof(v) is distinct from 'number' then raise exception using errcode='22023',message='Seating capacity needs a positive whole number'; end if;
      n:=(v#>>'{}')::numeric;
      if n<1 or n>9007199254740991 or n<>trunc(n) then raise exception using errcode='22023',message='Seating capacity needs a positive whole number'; end if;
    else
      if jsonb_typeof(v) is distinct from 'object' then raise exception using errcode='22023',message='Car declaration needs an answer state'; end if;
      status:=v->>'state';
      if status is null or status not in ('unanswered','unknown','known','not_applicable') or (status='not_applicable' and k not in ('battery_capacity_kwh','range_km')) then raise exception using errcode='22023',message='Invalid car answer state'; end if;
      if exists(select 1 from jsonb_object_keys(v) x where x not in ('state','value','other','basis')) then raise exception using errcode='22023',message='Unexpected car answer property'; end if;
      if status<>'known' then
        if v ? 'value' or v ? 'other' or v ? 'basis' then raise exception using errcode='22023',message='Unknown/unanswered/not-applicable cannot contain a value'; end if;
      elsif k in ('fuel_type','transmission','powertrain') then
        value:=v->>'value';
        if jsonb_typeof(v->'value') is distinct from 'string' or value not in (select unnest(case k when 'fuel_type' then array['petrol','diesel','cng','lpg','electric','hybrid','other'] when 'transmission' then array['manual','automatic','amt','cvt','dct','other'] else array['battery_electric','plug_in_hybrid','hybrid','other'] end)) or v ? 'basis' then raise exception using errcode='22023',message='Invalid seller declaration option'; end if;
        if value='other' then
          if jsonb_typeof(v->'other') is distinct from 'string' or length(btrim(v->>'other')) not between 1 and 80 then raise exception using errcode='22023',message='Other declaration needs 1–80 characters'; end if;
        elsif v ? 'other' then raise exception using errcode='22023',message='Other detail contradicts selected option'; end if;
      else
        if jsonb_typeof(v->'value') is distinct from 'number' or v ? 'other' then raise exception using errcode='22023',message='Known battery/range requires a finite numeric value'; end if;
        n:=(v->>'value')::numeric;
        if n<0 or n>9007199254740991 or (k='battery_capacity_kwh' and n=0) then raise exception using errcode='22023',message='Battery/range value outside supported range'; end if;
        if a->'powertrain'->>'state' is distinct from 'known' then raise exception using errcode='22023',message='Declare powertrain before known battery/range answers'; end if;
        if k='range_km' and v->>'basis' is distinct from 'electric_only' or k='battery_capacity_kwh' and v ? 'basis' then raise exception using errcode='22023',message='Range must mean electric-only distance per charge'; end if;
      end if;
    end if;
    normalized:=jsonb_set(normalized,array[k],v);
  end loop;
  return normalized;
end $$;

create function app_security.car_compatibility(raw jsonb,path jsonb,definition jsonb)
returns text language plpgsql immutable set search_path='' as $$
declare leaf text:=path->>2; mapping jsonb; segment text:=raw->>'segment'; body text:=raw->>'body_type';
begin
  if not definition->'knownSegments' ? segment then return 'incompatible'; end if;
  if leaf in ('Electric & Hybrid Cars','Vintage & Classic Cars') then return 'unresolved'; end if;
  if leaf='Luxury Cars' then return case when definition->'luxurySegments' ? segment then 'grouped' else 'incompatible' end; end if;
  select x into mapping from jsonb_array_elements(definition->'bodyMappings') x where x->>'body'=body;
  if found then return case when mapping->>'leaf'=leaf then mapping->>'kind' else 'incompatible' end; end if;
  return case when definition->'unresolvedBodies' ? body then 'unresolved' else 'incompatible' end;
end $$;

create function public.lookup_car_catalogue(p_category_id uuid,p_version_id uuid,p_brand_id uuid default null,p_search text default '',p_offset integer default 0,p_limit integer default 25,p_view text default 'mapped',p_selected_id uuid default null)
returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare path jsonb; definition jsonb; snapshot uuid; result jsonb;
begin
  if auth.uid() is null then raise exception 'Sign in required'; end if;
  if p_limit is null or p_limit not between 1 and 25 or p_offset is null or p_offset not between 0 and 10000 or p_search is null or length(p_search)>100 or p_view is null or p_view not in ('mapped','unresolved','review') then raise exception using errcode='22023',message='Invalid bounded car catalogue query'; end if;
  select p.source_path,v.definition,v.snapshot_id into path,definition,snapshot from public.car_category_contracts p join public.car_contract_versions v on v.id=p.version_id where p.category_id=p_category_id and p.version_id=p_version_id;
  if not found then raise exception using errcode='22023',message='Car category/version reference unavailable'; end if;
  with classified as (
    select m.id,m.brand_id,m.label,b.label brand,r.raw,r.selection_enabled,app_security.car_compatibility(r.raw,path,definition) compatibility
    from public.car_catalogue_rows r join public.car_models m on m.id=r.model_id join public.car_brands b on b.id=m.brand_id where r.snapshot_id=snapshot
  ), available as (
    select *,selection_enabled and raw->>'status' in ('on_sale','discontinued','import_only') and compatibility<>'incompatible' eligible, (raw->>'status'='import_only' or compatibility='unresolved') review_required from classified
  ), scoped as (
    select * from available where case when p_view='review' then true when p_view='mapped' then compatibility in ('exact','grouped') and eligible else compatibility='unresolved' and eligible end
  ), filtered as (
    select * from scoped where brand_id=p_brand_id and position(lower(p_search) in lower(label))>0
  ), page as (select * from filtered order by label,id offset p_offset limit p_limit)
  select jsonb_build_object('brands',coalesce((select jsonb_agg(x order by label) from (select distinct brand_id id,brand label from scoped) x),'[]'),'rows',coalesce((select jsonb_agg(to_jsonb(page) order by label,id) from page),'[]'),'total',(select count(*) from filtered),'offset',p_offset,'limit',p_limit,'selected',(select to_jsonb(available) from available where id=p_selected_id)) into result;
  return result;
end $$;

create function app_security.car_context_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare l public.listings; v public.car_contract_versions; p public.car_category_contracts; r public.car_catalogue_rows; m public.car_models; state text; retained boolean:=false;
begin
  select * into l from public.listings where id=new.listing_id;
  if not found then raise exception using errcode='22023',message='Car draft reference unavailable'; end if;
  if l.category_id<>new.category_id or l.status<>'draft' then raise exception 'Car context must match a draft category'; end if;
  select * into v from public.car_contract_versions where id=new.version_id;
  if not found then raise exception using errcode='22023', message='Car contract version unavailable'; end if;
  select * into p from public.car_category_contracts where category_id=new.category_id and version_id=new.version_id;
  if not found then raise exception using errcode='22023', message='Car category/version reference unavailable'; end if;
  if tg_op='UPDATE' then
    if new.listing_id<>old.listing_id then raise exception 'Listing context identity is immutable'; end if;
    if old.category_id=new.category_id and old.version_id<>new.version_id then raise exception 'Saved contract version cannot silently change'; end if;
    retained:=old.category_id=new.category_id and old.version_id=new.version_id and old.mode=new.mode and old.model_id is not distinct from new.model_id and old.brand_id is not distinct from new.brand_id and old.brand_text is not distinct from new.brand_text and old.model_text is not distinct from new.model_text;
  end if;
  if not retained and (not v.new_assignment_enabled or not exists(select 1 from public.categories c where c.id=new.category_id and c.is_active and c.new_listing_enabled)) then raise exception 'Car category/version closed for new assignment'; end if;
  new.classification_review_required:=new.mode='unresolved';
  if new.mode='not_listed' then
    -- Exact trimmed/case-insensitive recognition, no guessed aliases or fuzzy certification.
    select x.* into m from public.car_models x join public.car_brands b on b.id=x.brand_id where lower(btrim(b.label))=lower(btrim(new.brand_text)) and lower(btrim(x.label))=lower(btrim(new.model_text));
    if found then new.model_id:=m.id; raise exception 'Known brand/model must use its catalogue or unresolved route'; end if;
  elsif new.mode in ('catalogue','unresolved') then
    select * into r from public.car_catalogue_rows where snapshot_id=v.snapshot_id and model_id=new.model_id;
    if not found then raise exception using errcode='22023',message='Car model/version reference unavailable'; end if;
    select * into m from public.car_models where id=new.model_id and brand_id=new.brand_id;
    if not found then raise exception using errcode='22023',message='Car brand/model reference unavailable'; end if;
    state:=app_security.car_compatibility(r.raw,p.source_path,v.definition);
    if r.raw->>'status' not in ('on_sale','discontinued','import_only') then raise exception using errcode='22023',message='Unrecognized car lifecycle requires review'; end if;
    if state='incompatible' then raise exception 'Known model type, powertrain or mapping incompatible'; end if;
    if not retained and not r.selection_enabled then raise exception 'Model unavailable for new selection'; end if;
    if (new.mode='catalogue' and state not in ('exact','grouped')) or (new.mode='unresolved' and state<>'unresolved') then raise exception 'Incorrect model resolution mode'; end if;
  end if;
  new.classification_review_required:=new.mode in ('unresolved','not_listed') or (new.mode in ('catalogue','unresolved') and r.raw->>'status'='import_only');
  return new;
end $$;
create function app_security.car_listing_guard() returns trigger language plpgsql security definer set search_path='' as $$
declare fields jsonb; previous jsonb:='{}';
begin
  if tg_op='UPDATE' then
    previous:=old.category_attributes;
    if exists(select 1 from public.listing_car_contexts where listing_id=old.id) and new.category_id<>old.category_id and not exists(select 1 from public.car_category_contracts where category_id=new.category_id) then raise exception 'Car contract cannot be removed through another category'; end if;
  end if;
  if not exists(select 1 from public.car_category_contracts where category_id=new.category_id) then return new; end if;
  if new.status<>'draft' then raise exception 'Car review/publication is disabled for this milestone'; end if;
  select p.fields into fields from public.car_category_contracts p join public.listing_car_contexts c on c.category_id=p.category_id and c.version_id=p.version_id where c.listing_id=new.id and c.category_id=new.category_id;
  if fields is null then select p.fields into fields from public.car_category_contracts p join public.car_contract_versions v on v.id=p.version_id where p.category_id=new.category_id and v.contract_key='cars-draft-v1'; end if;
  new.category_attributes:=app_security.validate_car_answers(new.category_attributes,fields,previous);
  if new.price_type='free' and new.price_paise is distinct from 0 then raise exception 'Free price must be zero'; end if;
  return new;
end $$;
create function app_security.car_context_complete() returns trigger language plpgsql security definer set search_path='' as $$
declare listing uuid; l public.listings; c public.listing_car_contexts; fields jsonb;
begin
  if tg_table_name='listings' then listing:=new.id; else listing:=new.listing_id; end if;
  select * into l from public.listings where id=listing;
  if not found then return null; end if;
  select * into c from public.listing_car_contexts where listing_id=listing;
  if exists(select 1 from public.car_category_contracts where category_id=l.category_id) then
    if c.listing_id is null or c.category_id<>l.category_id or l.status<>'draft' then raise exception 'Atomic car context/category required; submission disabled'; end if;
    select p.fields into fields from public.car_category_contracts p where p.category_id=c.category_id and p.version_id=c.version_id;
    if not found then raise exception using errcode='22023',message='Car category/version reference unavailable'; end if;
    perform app_security.validate_car_answers(l.category_attributes,fields,l.category_attributes);
  elsif c.listing_id is not null then raise exception 'Car context cannot attach to unrelated category'; end if;
  return null;
end $$;
create function public.save_car_draft(p_listing_id uuid,p_listing jsonb,p_version_id uuid,p_resolution jsonb)
returns uuid language plpgsql security invoker set search_path='' as $$
#variable_conflict use_variable
declare id uuid; common public.listings; mode text:=p_resolution->>'mode'; brand uuid; model uuid; brand_text text; model_text text;
begin
  if auth.uid() is null then raise exception 'Sign in required'; end if;
  if jsonb_typeof(p_listing) is distinct from 'object' or jsonb_typeof(p_resolution) is distinct from 'object' then raise exception 'Malformed draft payload'; end if;
  if exists(select 1 from jsonb_object_keys(p_listing) x where x not in ('title','description','category_id','city_id','locality_id','condition','price_type','price_paise','pin_code','landmark','category_attributes')) then raise exception 'Unexpected common field'; end if;
  if mode is null or mode not in ('unanswered','catalogue','unresolved','not_listed') then raise exception 'Invalid resolution mode'; end if;
  if exists(select 1 from jsonb_object_keys(p_resolution) x where x not in (select unnest(case when mode='unanswered' then array['mode','brand_id'] when mode='not_listed' then array['mode','brand_text','model_text'] else array['mode','brand_id','model_id'] end))) then raise exception 'Unexpected/forged resolution field'; end if;
  select * into common from jsonb_populate_record(null::public.listings,p_listing);
  if length(btrim(common.title))<3 or length(common.title)>150 then raise exception 'Title must be 3–150 characters'; end if;
  if jsonb_typeof(p_listing->'price_paise')='number' and (p_listing->>'price_paise')::numeric<>trunc((p_listing->>'price_paise')::numeric) then raise exception 'Price paise must be whole'; end if;
  brand:=nullif(p_resolution->>'brand_id','')::uuid; model:=nullif(p_resolution->>'model_id','')::uuid;
  brand_text:=p_resolution->>'brand_text'; model_text:=p_resolution->>'model_text';
  if p_listing_id is null then
    insert into public.listings(title,description,category_id,city_id,locality_id,condition,price_type,price_paise,pin_code,landmark,category_attributes)
    values(common.title,common.description,common.category_id,common.city_id,common.locality_id,common.condition,common.price_type,common.price_paise,common.pin_code,common.landmark,coalesce(common.category_attributes,'{}')) returning listings.id into id;
  else
    -- Row lock serializes same-ID updates, and prevents non-owner and non-vehicle conversion.
    perform 1 from public.listings l join public.listing_car_contexts c on c.listing_id=l.id where l.id=p_listing_id and l.seller_id=auth.uid() and l.status='draft' for update of l;
    if not found then raise exception 'Owned car draft required'; end if;
    update public.listings set title=common.title,description=common.description,category_id=common.category_id,city_id=common.city_id,locality_id=common.locality_id,condition=common.condition,price_type=common.price_type,price_paise=common.price_paise,pin_code=common.pin_code,landmark=common.landmark,category_attributes=coalesce(common.category_attributes,'{}') where listings.id=p_listing_id returning listings.id into id;
    if id is null then raise exception 'Draft update denied'; end if;
  end if;
  if p_listing_id is null then
    insert into public.listing_car_contexts(listing_id,category_id,version_id,mode,brand_id,model_id,brand_text,model_text)
    values(id,common.category_id,p_version_id,mode,brand,model,brand_text,model_text);
  else
    update public.listing_car_contexts set category_id=common.category_id,version_id=p_version_id,mode=mode,brand_id=brand,model_id=model,brand_text=brand_text,model_text=model_text where listing_id=id;
  end if;
  return id;
end $$;
create trigger car_context_guard before insert or update on public.listing_car_contexts for each row execute function app_security.car_context_guard();
create trigger zz_car_listing_guard before insert or update on public.listings for each row execute function app_security.car_listing_guard();
create constraint trigger car_listing_context_complete after insert or update on public.listings deferrable initially deferred for each row execute function app_security.car_context_complete();
create constraint trigger car_context_listing_complete after insert or update on public.listing_car_contexts deferrable initially deferred for each row execute function app_security.car_context_complete();
revoke all on function app_security.car_context_guard(),app_security.car_listing_guard(),app_security.car_context_complete(),app_security.validate_car_answers(jsonb,jsonb,jsonb),app_security.car_compatibility(jsonb,jsonb,jsonb) from public,anon,authenticated,service_role;
grant execute on function app_security.car_compatibility(jsonb,jsonb,jsonb) to authenticated;
revoke all on function public.save_car_draft(uuid,jsonb,uuid,jsonb),public.lookup_car_catalogue(uuid,uuid,uuid,text,integer,integer,text,uuid) from public,anon,service_role;
grant execute on function public.save_car_draft(uuid,jsonb,uuid,jsonb),public.lookup_car_catalogue(uuid,uuid,uuid,text,integer,integer,text,uuid) to authenticated;

